    async def list_servers_iter(
        self,
        *,
        zone: str | None = None,
        per_page: int | None = None,
        organization: str | None = None,
        project: str | None = None,
        name: str | None = None,
        private_ip: str | None = None,
        without_ip: bool | None = None,
        with_ip: str | None = None,
        commercial_type: str | None = None,
        state: ServerState | None = None,
        tags: str | None = None,
        private_network: str | None = None,
        order: ListServersRequestOrder | None = None,
        private_networks: str | None = None,
        private_nic_mac_address: str | None = None,
        servers: str | None = None,
    ) -> AsyncIterator[Server]:
        """Iterate over every item of `list_servers`, page after page."""

        async def fetch(page: int) -> tuple[ListServersResponse, int | None]:
            response = await self._client.request(
                "GET",
                self._client.path(
                    "/instance/v1/zones/{zone}/servers", zone=self._client.zone(zone)
                ),
                params={
                    "per_page": per_page,
                    "page": page,
                    "organization": organization,
                    "project": project,
                    "name": name,
                    "private_ip": private_ip,
                    "without_ip": without_ip,
                    "with_ip": with_ip,
                    "commercial_type": commercial_type,
                    "state": state,
                    "tags": tags,
                    "private_network": private_network,
                    "order": order,
                    "private_networks": private_networks,
                    "private_nic_mac_address": private_nic_mac_address,
                    "servers": servers,
                },
            )
            result = ListServersResponse.model_validate(response.json())
            header = response.headers.get("x-total-count")
            return result, int(header) if header else None

        async for entry in paginate(
            fetch,
            lambda page: page[0].servers or [],
            lambda page: page[1],
        ):
            yield entry

    async def list_servers_all(
        self,
        *,
        zone: str | None = None,
        per_page: int | None = None,
        organization: str | None = None,
        project: str | None = None,
        name: str | None = None,
        private_ip: str | None = None,
        without_ip: bool | None = None,
        with_ip: str | None = None,
        commercial_type: str | None = None,
        state: ServerState | None = None,
        tags: str | None = None,
        private_network: str | None = None,
        order: ListServersRequestOrder | None = None,
        private_networks: str | None = None,
        private_nic_mac_address: str | None = None,
        servers: str | None = None,
    ) -> list[Server]:
        """Every item of `list_servers`, all pages read."""
        return [
            entry
            async for entry in self.list_servers_iter(
                zone=zone,
                per_page=per_page,
                organization=organization,
                project=project,
                name=name,
                private_ip=private_ip,
                without_ip=without_ip,
                with_ip=with_ip,
                commercial_type=commercial_type,
                state=state,
                tags=tags,
                private_network=private_network,
                order=order,
                private_networks=private_networks,
                private_nic_mac_address=private_nic_mac_address,
                servers=servers,
            )
        ]

    async def create_server(
        self,
        *,
        name: str,
        commercial_type: str,
        zone: str | None = None,
        dynamic_ip_required: bool | None = None,
        routed_ip_enabled: bool | None = None,
        image: str | None = None,
        volumes: dict[str, VolumeServerTemplate] | None = None,
        enable_ipv6: bool | None = None,
        public_ip: str | None = None,
        public_ips: list[Any] | None = None,
        boot_type: BootType | None = None,
        organization: str | None = None,
        project: str | None = None,
        tags: list[str] | None = None,
        security_group: str | None = None,
        placement_group: str | None = None,
        admin_password_encryption_ssh_key_id: str | None = None,
        protected: bool | None = None,
    ) -> CreateServerResponse:
        """
        Create an Instance

        Create a new Instance of the specified commercial type in the specified zone.
        Pay attention to the volumes parameter, which takes an object which can be used
        in different ways to achieve different behaviors.
        Get more information in the [Technical Information](#technical-information)
        section of the introduction.

        Args:
            zone: The zone you want to target
            name: Instance name.
            dynamic_ip_required: Define if a dynamic IPv4 is required for the Instance.
                By default, `dynamic_ip_required` is true, a dynamic ip is attached to
                the instance (if no flexible ip is already attached).
            routed_ip_enabled: If true, configure the Instance so it uses the new routed
                IP mode.
            commercial_type: Define the Instance commercial type (i.e. GP1-S).
            image: Instance image ID or label. When an image label is used, it will be
                converted to the latest image available on the Marketplace. By default,
                the selected local image will be the `instance_sbs` local image. If an
                `l_ssd` volume is specified in the volumes argument, an `instance_local`
                local image will be selected instead.
            volumes: Volumes attached to the server.
            enable_ipv6: True if IPv6 is enabled on the server (deprecated and always
                `False` when `routed_ip_enabled` is `True`).
            public_ip: ID of the reserved IP to attach to the Instance.
            public_ips: A list of reserved IP IDs to attach to the Instance.
            boot_type: Boot type to use.
            organization: Instance Organization ID. Precisely one of project,
                organization can be set.
            project: Instance Project ID. Precisely one of project, organization can be
                set.
            tags: Instance tags.
            security_group: Security group ID.
            placement_group: Placement group ID if Instance must be part of a placement
                group.
            admin_password_encryption_ssh_key_id: UUID of the SSH RSA key that will be
                used to encrypt the initial admin password for OS requiring it.
                Mandatory for Windows OS. The public_key value of this key is used to
                encrypt the admin password.
            protected: True to activate server protection option.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/instance/v1/zones/{zone}/servers", zone=self._client.zone(zone)
            ),
            body={
                "name": name,
                "dynamic_ip_required": dynamic_ip_required,
                "routed_ip_enabled": routed_ip_enabled,
                "commercial_type": commercial_type,
                "image": image,
                "volumes": volumes,
                "enable_ipv6": enable_ipv6,
                "public_ip": public_ip,
                "public_ips": public_ips,
                "boot_type": boot_type,
                "tags": tags,
                "security_group": security_group,
                "placement_group": placement_group,
                "admin_password_encryption_ssh_key_id": admin_password_encryption_ssh_key_id,
                "protected": protected,
                **self._client.owner(
                    project_id=project,
                    organization_id=organization,
                    keys=("project", "organization"),
                ),
            },
        )
        return CreateServerResponse.model_validate(data)

