    async def server_action(
        self,
        *,
        server_id: str,
        zone: str | None = None,
        action: ServerAction | None = None,
        name: str | None = None,
        volumes: dict[str, ServerActionRequestVolumeBackupTemplate] | None = None,
        disable_ipv6: bool | None = None,
    ) -> ServerActionResponse:
        """
        Perform action

        Perform an action on an Instance.
        Available actions are:
        * `poweron`: Start a stopped Instance.
        * `poweroff`: Fully stop the Instance and release the hypervisor slot.
        * `stop_in_place`: Stop the Instance, but keep the slot on the hypervisor.
        * `reboot`: Stop the instance and restart it.
        * `backup`: Create an image with all the volumes of an Instance.
        * `terminate`: Delete the Instance along with its attached local volumes.
        * `enable_routed_ip`: Migrate the Instance to the new network stack.

        The `terminate` action will result in the deletion of `l_ssd` and `scratch`
        volumes types, `sbs_volume` volumes will only be detached.
        If you want to preserve your `l_ssd` volumes, you should stop your Instance,
        detach the volumes to be preserved, then delete your Instance.

        The `backup` action can be done with:
        * No `volumes` key in the body: an image is created with snapshots of all the
        server volumes, except for the `scratch` volumes types.
        * `volumes` key in the body with a dictionary as value, in this dictionary
        volumes UUID as keys and empty dictionaries as values : an image is created with
        the snapshots of the volumes in `volumes` key. `scratch` volumes types can't be
        shapshotted.

        Args:
            zone: The zone you want to target
            server_id: UUID of the Instance.
            action: Action to perform on the Instance.
            name: Name of the backup you want to create. Name of the backup you want to
                create. This field should only be specified when performing a backup
                action.
            volumes: For each volume UUID, the snapshot parameters of the volume. For
                each volume UUID, the snapshot parameters of the volume. This field
                should only be specified when performing a backup action.
            disable_ipv6: Disable IPv6 on the Instance (true by default). Disable IPv6
                on the Instance while performing migration to routed IPs. This field
                should only be specified when performing a enable_routed_ip action.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/instance/v1/zones/{zone}/servers/{server_id}/action",
                zone=self._client.zone(zone),
                server_id=server_id,
            ),
            body={
                "action": action,
                "name": name,
                "volumes": volumes,
                "disable_ipv6": disable_ipv6,
            },
        )
        return ServerActionResponse.model_validate(data)

